import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type CinematicTitleRevealProps = Record<string, any>;

// Sub-components for visual layers
const FilmGrain: React.FC<{ opacity: number; frame: number; baseIntensity: number }> = ({ opacity, frame, baseIntensity }) => {
  const tx = (random(`grain-x-${frame}`) - 0.5) * 20;
  const ty = (random(`grain-y-${frame}`) - 0.5) * 20;
  
  return (
    <AbsoluteFill style={{ 
      opacity: opacity * (baseIntensity / 0.15),
      mixBlendMode: "screen",
      pointerEvents: "none",
      overflow: "hidden"
    }}>
      <div style={{
        position: "absolute",
        top: "-20%",
        left: "-20%",
        width: "140%",
        height: "140%",
        transform: `translate(${tx}%, ${ty}%)`,
      }}>
        <svg width="100%" height="100%">
           <filter id="noiseFilter">
             <feTurbulence type="fractalNoise" baseFrequency="0.75" numOctaves="3" stitchTiles="stitch" />
             <feColorMatrix type="saturate" values="0.3" />
           </filter>
           <rect width="100%" height="100%" filter="url(#noiseFilter)" opacity="0.6" />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

const Scanlines: React.FC<{ opacity: number; frame: number }> = ({ opacity, frame }) => {
  const driftY = (frame * 1.5) % 100;
  return (
    <AbsoluteFill style={{ 
      opacity, 
      pointerEvents: "none", 
      background: "repeating-linear-gradient(to bottom, transparent 0px, transparent 4px, rgba(0,0,0,0.15) 5px, rgba(0,0,0,0.15) 6px)",
      backgroundPosition: `0px ${driftY}px`
    }} />
  );
};

const LightBloom: React.FC<{ opacity: number; scale: number }> = ({ opacity, scale }) => {
  return (
    <AbsoluteFill style={{
      opacity,
      transform: `scale(${scale})`,
      background: "radial-gradient(circle at center, rgba(230,230,225,0.12) 0%, rgba(230,230,225,0.03) 30%, transparent 70%)",
      mixBlendMode: "screen",
      pointerEvents: "none"
    }} />
  );
};

const StaticFlickers: React.FC<{ frame: number; opacity: number }> = ({ frame, opacity }) => {
  if (opacity === 0) return null;
  const val = random(`static-${frame}`);
  if (val < 0.8) return null;
  
  const top = random(`top-${frame}`) * 100;
  const height = random(`height-${frame}`) * 10 + 1;
  const width = random(`width-${frame}`) * 50 + 20;
  const left = random(`left-${frame}`) * 50;
  
  return (
    <AbsoluteFill style={{ opacity }}>
      <div style={{ 
        position: "absolute", 
        top: `${top}%`, 
        left: `${left}%`, 
        width: `${width}%`, 
        height, 
        backgroundColor: "#fff", 
        opacity: 0.15,
        mixBlendMode: "overlay"
      }} />
    </AbsoluteFill>
  );
};

const Flashes: React.FC<{ isPhase2: boolean; frame: number }> = ({ isPhase2, frame }) => {
  if (!isPhase2) return null;
  const val = random(`flash-${frame}`);
  if (val < 0.92) return null;
  
  const isSprocket = random(`sprocket-${frame}`) > 0.5;
  
  if (isSprocket) {
    return (
      <AbsoluteFill style={{ flexDirection: "row", justifyContent: "space-between", padding: "0 40px", alignItems: "center", opacity: 0.08 }}>
        <div style={{ width: 60, height: 120, backgroundColor: "#e8e6e1", borderRadius: 15 }} />
        <div style={{ width: 60, height: 120, backgroundColor: "#e8e6e1", borderRadius: 15 }} />
      </AbsoluteFill>
    );
  } else {
    const top = random(`timeline-top-${frame}`) * 80 + 10;
    return (
      <AbsoluteFill style={{ justifyContent: "center", opacity: 0.06 }}>
        <div style={{ position: "absolute", top: `${top}%`, left: "10%", right: "10%", height: 3, backgroundColor: "#e8e6e1" }} />
        <div style={{ position: "absolute", top: `${top}%`, left: "25%", width: "30%", height: 15, backgroundColor: "#e8e6e1", marginTop: -6 }} />
      </AbsoluteFill>
    );
  }
};

const TextContent: React.FC<{
  title: string;
  subtitle: string;
  primaryTextColor: string;
  titleOpacity: number;
  titleBlur: number;
  titleGhostOffset: number;
  titleGhostOpacity: number;
  phase3Distortion: number;
  subtitleOpacity: number;
  subtitleBlur: number;
  subtitleGhostOffset: number;
  subtitleGhostOpacity: number;
  subtitleDistortion: number;
}> = ({
  title, subtitle, primaryTextColor,
  titleOpacity, titleBlur, titleGhostOffset, titleGhostOpacity, 
  phase3Distortion,
  subtitleOpacity, subtitleBlur, subtitleGhostOffset, subtitleGhostOpacity, subtitleDistortion
}) => {
  const { width } = useVideoConfig();
  const words = title.split(" ");
  const subtitleWords = subtitle.split(" ");
  
  const titleSize = width * 0.15; 
  const subtitleSize = width * 0.24;
  
  const baseTitleStyle: React.CSSProperties = {
    fontSize: titleSize,
    fontWeight: 900, 
    textTransform: "uppercase",
    letterSpacing: "0.05em",
    margin: 0,
    fontFamily: interFamily,
    textAlign: "center",
    width: "100%",
    lineHeight: 1.0 
  };

  const baseSubtitleStyle: React.CSSProperties = {
    fontSize: subtitleSize,
    fontWeight: 800, 
    textTransform: "uppercase",
    letterSpacing: "0.1em",
    lineHeight: 1.0,
    margin: 0,
    fontFamily: interFamily,
    textAlign: "center",
    width: "100%",
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "100%", width: "100%", padding: "0 5%" }}>
      
      <div style={{ position: "relative", display: "flex", justifyContent: "center", alignItems: "center", width: "100%" }}>
         {/* Cyan Ghost Title */}
         <h1 style={{ 
           ...baseTitleStyle,
           color: "rgba(0, 255, 255, 0.9)", 
           position: "absolute", 
           transform: `translateX(calc(-${titleGhostOffset}px + ${phase3Distortion}px))`, 
           opacity: titleGhostOpacity, 
           mixBlendMode: "screen", 
           filter: `blur(${titleBlur + 1}px)`
         }}>
           {words.map((word, i) => (
             <span key={`cyan-${i}`} style={{ display: "block" }}>{word}</span>
           ))}
         </h1>
         
         {/* Red Ghost Title */}
         <h1 style={{ 
           ...baseTitleStyle,
           color: "rgba(255, 0, 0, 0.9)", 
           position: "absolute", 
           transform: `translateX(calc(${titleGhostOffset}px - ${phase3Distortion}px))`, 
           opacity: titleGhostOpacity, 
           mixBlendMode: "screen", 
           filter: `blur(${titleBlur + 1}px)`
         }}>
           {words.map((word, i) => (
             <span key={`red-${i}`} style={{ display: "block" }}>{word}</span>
           ))}
         </h1>
         
         {/* Main Title */}
         <h1 style={{ 
           ...baseTitleStyle,
           color: primaryTextColor, 
           position: "relative", 
           opacity: titleOpacity,
           filter: `blur(${titleBlur}px)`,
           mixBlendMode: "screen"
         }}>
           {words.map((word, i) => (
             <span key={`main-${i}`} style={{ display: "block" }}>{word}</span>
           ))}
         </h1>
      </div>

      {/* Subtitle Block matching Title Style exactly */}
      <div style={{ 
        position: "relative", 
        display: "flex", 
        justifyContent: "center", 
        alignItems: "center", 
        width: "100%", 
        marginTop: width * 0.08,
      }}>
         {/* Cyan Ghost Subtitle */}
         <h2 style={{ 
           ...baseSubtitleStyle,
           color: "rgba(0, 255, 255, 0.9)", 
           position: "absolute", 
           transform: `translateX(calc(-${subtitleGhostOffset}px + ${subtitleDistortion}px))`, 
           opacity: subtitleGhostOpacity, 
           mixBlendMode: "screen", 
           filter: `blur(${subtitleBlur + 1}px)`
         }}>
           {subtitleWords.map((word, i) => (
             <span key={`cyan-sub-${i}`} style={{ display: "block" }}>{word}</span>
           ))}
         </h2>
         
         {/* Red Ghost Subtitle */}
         <h2 style={{ 
           ...baseSubtitleStyle,
           color: "rgba(255, 0, 0, 0.9)", 
           position: "absolute", 
           transform: `translateX(calc(${subtitleGhostOffset}px - ${subtitleDistortion}px))`, 
           opacity: subtitleGhostOpacity, 
           mixBlendMode: "screen", 
           filter: `blur(${subtitleBlur + 1}px)`
         }}>
           {subtitleWords.map((word, i) => (
             <span key={`red-sub-${i}`} style={{ display: "block" }}>{word}</span>
           ))}
         </h2>

         {/* Main Subtitle */}
         <h2 style={{ 
           ...baseSubtitleStyle,
           color: primaryTextColor, 
           position: "relative", 
           opacity: subtitleOpacity,
           filter: `blur(${subtitleBlur}px)`,
           mixBlendMode: "screen"
         }}>
           {subtitleWords.map((word, i) => (
             <span key={`main-sub-${i}`} style={{ display: "block" }}>{word}</span>
           ))}
         </h2>
      </div>
    </div>
  );
};

const TearOverlay: React.FC<{ frame: number; tearProgress: number; children: React.ReactNode }> = ({ frame, tearProgress, children }) => {
  if (tearProgress === 0) return null;
  
  const tearY = interpolate(tearProgress, [0, 1], [-20, 120]);
  const tearHeight = 15; 
  const shiftX = Math.sin(frame) * 30 * tearProgress;
  
  return (
    <AbsoluteFill style={{
      clipPath: `polygon(0% ${tearY}%, 100% ${tearY}%, 100% ${tearY + tearHeight}%, 0% ${tearY + tearHeight}%)`,
      transform: `translateX(${shiftX}px)`,
      filter: "blur(2px)",
      opacity: 0.9,
      mixBlendMode: "screen",
      backgroundColor: "rgba(255,255,255,0.03)"
    }}>
      {children}
    </AbsoluteFill>
  );
};

// Main Component
const CinematicTitleReveal: React.FC<CinematicTitleRevealProps> = ({
  backgroundColor = "rgba(5, 5, 5, 1)",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "Malloy Studio",
  subtitle = "2026 Reel",
  primaryTextColor = "rgba(232, 230, 225, 1)",
  grainIntensity = 0.15,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const durationInFrames = Math.round(durationInSeconds * fps);
  
  // Phase Milestones
  const p1End = Math.round(durationInFrames * 0.3); 
  const p2End = Math.round(durationInFrames * 0.625); 

  // Text resolving at 1.5 seconds exactly
  const clarifyStart = Math.round(fps * 1.5);
  const clarifyEnd = clarifyStart + fps; // Resolve over 1 second

  // Logic to prevent parser errors for background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Interpolations ---
  
  // Phase 1: Noise & Scanlines emerge
  const grainOpacity = interpolate(frame, [0, p1End], [0, 0.4], { extrapolateRight: "clamp" });
  const scanlineOpacity = interpolate(frame, [0, p1End], [0, 0.25], { extrapolateRight: "clamp" });

  // Phase 2: Light Bloom emerges
  const isPhase2 = frame >= p1End && frame < p2End;
  const lightBloomOpacity = interpolate(frame, [p1End, p2End], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const lightBloomScale = interpolate(frame, [p1End, p2End], [0.8, 1.2], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Text resolving (Never fully resolving to pure white to maintain red/cyan style)
  const titleOpacity = interpolate(frame, [clarifyStart, clarifyEnd], [0, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const titleBlur = interpolate(frame, [clarifyStart, clarifyEnd], [20, 0.5], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const titleGhostOffset = interpolate(frame, [clarifyStart, clarifyEnd], [25, 5], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const titleGhostOpacity = interpolate(frame, [clarifyStart, clarifyEnd], [0.9, 0.75], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  // High distortion initially, easing out to a very subtle shimmer as it comes into focus
  const titleJitterIntensity = interpolate(frame, [clarifyStart, clarifyEnd], [8, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const phase3Distortion = (frame > clarifyStart)
    ? (random(`distort-${frame}`) - 0.5) * titleJitterIntensity
    : 0;

  // Subtitle logic: Appears at 1.5s, ghost style persists
  const subStart = clarifyStart; 
  const subMid = subStart + Math.round(fps * 0.5); 
  const subEnd = subMid + Math.round(fps * 1.0); 

  const subtitleGhostOpacity = interpolate(frame, [subStart, subMid, subEnd], [0, 0.9, 0.75], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const subtitleOpacity = interpolate(frame, [subMid, subEnd], [0, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const subtitleBlur = interpolate(frame, [subStart, subMid, subEnd], [20, 20, 0.5], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const subtitleGhostOffset = interpolate(frame, [subStart, subMid, subEnd], [25, 25, 5], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  // High distortion initially, easing out to a very subtle shimmer
  const subtitleJitterIntensity = interpolate(frame, [subStart, subMid, subEnd], [0, 8, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const subtitleDistortion = (frame > subStart)
    ? (random(`sub-distort-${frame}`) - 0.5) * subtitleJitterIntensity
    : 0;

  // Phase 4 & Continuous: Global movement, Tear, and Fade
  const globalScale = interpolate(frame, [0, durationInFrames], [1, 1.05]);
  
  const driftX = Math.cos(frame / 12) * 3;
  const driftY = Math.sin(frame / 15) * 6 + Math.cos(frame / 9) * 4;
  // Reduced camera weave to lower overall jitter
  const weaveX = (random(`weaveX-${frame}`) - 0.5) * 0.5;
  const weaveY = (random(`weaveY-${frame}`) - 0.5) * 0.5;
  const totalDriftX = driftX + weaveX;
  const totalDriftY = driftY + weaveY;

  const fadeOutStart = durationInFrames - Math.round(fps * 0.2);
  const globalFade = interpolate(frame, [fadeOutStart, durationInFrames], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const tearStart = durationInFrames - Math.round(fps * 0.3);
  const tearProgress = interpolate(frame, [tearStart, durationInFrames], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Projector hum / subtle flicker
  const globalFlicker = interpolate(random(`flicker-${frame}`), [0, 1], [0.96, 1]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* 1. Camera transformed content (Bloom, Flashes, Text) */}
      <AbsoluteFill style={{ 
        opacity: globalFade * globalFlicker, 
        transform: `scale(${globalScale}) translateY(${totalDriftY}px) translateX(${totalDriftX}px)`,
        transformOrigin: "center center"
      }}>
         <LightBloom opacity={lightBloomOpacity} scale={lightBloomScale} />
         <Flashes isPhase2={isPhase2} frame={frame} />
         
         <TextContent 
           title={title} 
           subtitle={subtitle}
           primaryTextColor={primaryTextColor}
           titleOpacity={titleOpacity}
           titleBlur={titleBlur}
           titleGhostOffset={titleGhostOffset}
           titleGhostOpacity={titleGhostOpacity}
           phase3Distortion={phase3Distortion}
           subtitleOpacity={subtitleOpacity}
           subtitleBlur={subtitleBlur}
           subtitleGhostOffset={subtitleGhostOffset}
           subtitleGhostOpacity={subtitleGhostOpacity}
           subtitleDistortion={subtitleDistortion}
         />

         {tearProgress > 0 && (
           <TearOverlay frame={frame} tearProgress={tearProgress}>
             <TextContent 
               title={title} 
               subtitle={subtitle}
               primaryTextColor={primaryTextColor}
               titleOpacity={titleOpacity}
               titleBlur={titleBlur}
               titleGhostOffset={titleGhostOffset}
               titleGhostOpacity={titleGhostOpacity}
               phase3Distortion={phase3Distortion}
               subtitleOpacity={subtitleOpacity}
               subtitleBlur={subtitleBlur}
               subtitleGhostOffset={subtitleGhostOffset}
               subtitleGhostOpacity={subtitleGhostOpacity}
               subtitleDistortion={subtitleDistortion}
             />
           </TearOverlay>
         )}
      </AbsoluteFill>
      
      {/* 2. Screen-space artifacts (Grain, Scanlines, Static) */}
      <AbsoluteFill style={{ opacity: globalFade }}>
         <FilmGrain opacity={grainOpacity} frame={frame} baseIntensity={grainIntensity} />
         <Scanlines opacity={scanlineOpacity} frame={frame} />
         <StaticFlickers frame={frame} opacity={scanlineOpacity} />
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default CinematicTitleReveal;